def is_undulating(n):
    s = str(n)
    if len(s) < 3:
        return False

    a, b = s[0], s[1]
    if a == b:
        return False

    for i in range(len(s)):
        if i % 2 == 0 and s[i] != a:
            return False
        if i % 2 == 1 and s[i] != b:
            return False

    return True
